class Solution {

    /**
     * @param Integer $n
     * @param Integer $m
     * @param Integer $k
     * @return Integer
     */
    function numOfArrays($n, $m, $k) {
        $mod = 1000000007;

        // dp[i][j][kk] = number of arrays of length i, max element j, cost kk
        // i from 1 to n, j from 1 to m, kk from 1 to k
        // Since constraints are small, DP is feasible

        // Initialize 3D DP array with zeros
        $dp = [];
        for ($i = 0; $i <= $n; $i++) {
            $dp[$i] = [];
            for ($j = 0; $j <= $m; $j++) {
                $dp[$i][$j] = array_fill(0, $k + 1, 0);
            }
        }

        // Base case: for arrays of length 1, max element j, cost 1 means array [j]
        for ($j = 1; $j <= $m; $j++) {
            $dp[1][$j][1] = 1;
        }

        for ($i = 2; $i <= $n; $i++) {
            for ($j = 1; $j <= $m; $j++) {
                for ($kk = 1; $kk <= $k; $kk++) {
                    if ($dp[$i - 1][$j][$kk] > 0) {
                        // Add numbers <= current max j without increasing cost
                        // For each value l (1 <= l <= j), append l, max remains j
                        $dp[$i][$j][$kk] = ($dp[$i][$j][$kk] + ($dp[$i - 1][$j][$kk] * $j) % $mod) % $mod;
                    }
                    // We do not add here because this would overcount the same state multiple times.
                    // Instead, we consider new max.

                    // Next for $j < next max, handled below
                }
            }
            // Now handle new max elements for position i
            // For each new max value nj from 1 to m
            // we need to consider arrays of length i-1 with max j < nj and cost kk-1
            for ($nj = 1; $nj <= $m; $nj++) {
                for ($kk = 2; $kk <= $k; $kk++) {
                    $sum = 0;
                    for ($j = 1; $j < $nj; $j++) {
                        $sum = ($sum + $dp[$i - 1][$j][$kk - 1]) % $mod;
                    }
                    if ($sum > 0) {
                        $dp[$i][$nj][$kk] = ($dp[$i][$nj][$kk] + $sum) % $mod;
                    }
                }
            }
        }

        // Sum over all max values for cost = k for length = n
        $result = 0;
        for ($j = 1; $j <= $m; $j++) {
            $result = ($result + $dp[$n][$j][$k]) % $mod;
        }
        return $result;
    }
}

